"""Real compiled UI and PDF.js worker, paired with PDFs generated by Rust tests.
Run formular_workflow with BAUPROJEKT_PDF_ARTEFAKTE before this test.
"""
from pathlib import Path
import json,base64,os
from playwright.sync_api import sync_playwright,expect
root=Path(__file__).resolve().parent
artefacts=Path(os.environ.get('BAUPROJEKT_PDF_ARTEFAKTE','/workspace/review-main/pdf-ablage'))
workflow=json.loads((artefacts/'workflow.json').read_text())
pdfs={name:base64.b64encode((artefacts/(name+'.pdf')).read_bytes()).decode() for name in ['original','vorlage','ausgefuellt']}
out=Path(os.environ.get('BAUPROJEKT_PDF_UI_ARTEFAKTE',str(root.parents[2]/'docs/pdf-ablage')));out.mkdir(parents=True,exist_ok=True)
custom='''
const originalInvoke=window.__TAURI_INTERNALS__.invoke;
const wf=window.pdfWorkflow;
window.pdfDocs=[wf.original];window.allowed=false;window.failTemplate=true;window.failFolder=true;window.currentRoot='/tmp/BauProjektIO';
const f=[{name:'Vorname',beschriftung:'Vorname',art:'text',wert:null,optionen:[],schreibgeschuetzt:false,max_laenge:4000},{name:'Zustimmung',beschriftung:'Zustimmung',art:'ankreuzfeld',wert:null,optionen:['Yes'],schreibgeschuetzt:false,max_laenge:null}];
window.__TAURI_INTERNALS__.invoke=async(cmd,args={})=>{
 if(['dokumente_auflisten','pdf_vorschau','formular_vorlage_erstellen','formular_analysieren','formular_ausfuellen','dokument_exportieren','ablage_status','ablage_wechseln','projektordner_exportieren','plugin:dialog|message','plugin:dialog|save','plugin:dialog|open'].includes(cmd))window.calls.push({cmd,args:JSON.parse(JSON.stringify(args))});
 switch(cmd){
 case 'dokumente_auflisten':return args.projektId===wf.projekt.id?window.pdfDocs:[];
 case 'pdf_vorschau':{const name=args.dokumentId===wf.original.document_id?'original':args.dokumentId===wf.vorlage.document_id?'vorlage':'ausgefuellt';return {dokument:wf[name],pdf_base64:window.pdfBytes[name],seiten:[{nummer:1,breite_mm:595*25.4/72,hoehe_mm:842*25.4/72,rotation:0,platzierbar:true}],felder:name==='original'?[]:f};}
 case 'formular_vorlage_erstellen':if(window.failTemplate)throw {art:'validierung',meldung:'Test: Vorlage konnte nicht gespeichert werden'};window.pdfDocs.push(wf.vorlage);return wf.vorlage;
 case 'formular_analysieren':return {dokument:wf.vorlage,felder:f,vorlage:null,vorschlag:{}};
 case 'formular_ausfuellen':window.pdfDocs.push(wf.ausgefuellt);return wf.ausgefuellt;
 case 'dokument_exportieren':return;
 case 'ablage_status':return {modus:'Einzelplatz',root:window.currentRoot,datenbank:'/tmp/bauprojekt.db',wechsel_erlaubt:window.testUser.rolle==='administrator',hinweis:'Die Projektdatenbank bleibt am bisherigen Ort.'};
 case 'ablage_wechseln':if(window.failFolder)throw {art:'datei',meldung:'Test: Ziel konnte nicht geschrieben werden'};window.currentRoot=args.pfad;return 3;
 case 'projektordner_exportieren':return {ordner:'/tmp/Projektformular/Dokumente',dateien:3,neu:3};
 case 'plugin:dialog|message':return window.allowed?(args.buttons?.OkCancelCustom?.[0]??args.buttons?.YesNoCustom?.[0]??'Kopieren und wechseln'):'Weiter bearbeiten';
 case 'plugin:dialog|save':return '/tmp/ausgefuellt.pdf';
 case 'plugin:dialog|open':return '/tmp/NeueProjektablage';
 default:return originalInvoke(cmd,args);
 }
};
'''
checks=[];errors=[]
with sync_playwright() as p:
 browser=p.chromium.launch(headless=True,executable_path='/usr/bin/chromium')
 page=browser.new_page(viewport={'width':1440,'height':1000})
 page.on('pageerror',lambda e:errors.append(str(e)))
 page.add_init_script('window.fixture='+json.dumps(workflow['projekt'])+';window.pdfWorkflow='+json.dumps(workflow)+';window.pdfBytes='+json.dumps(pdfs)+';\n'+(root/'tauri-mock.js').read_text()+'\n'+custom)
 page.goto(os.environ.get('BAUPROJEKT_UI_URL','http://127.0.0.1:1431'))
 page.locator('.projekttabelle').get_by_role('button',name='Projektformular',exact=True).click()
 page.locator('.aktennavigation').get_by_role('button',name='Dokumente',exact=True).click()
 page.get_by_role('button',name='Eigene Felder / Vorlage …',exact=True).click()
 page.get_by_role('button',name='Textfeld hinzufügen',exact=True).click()
 page.get_by_label('Feldname / Platzhalter',exact=True).fill('<Vorname>')
 page.get_by_label('Beschriftung in der Maske',exact=True).fill('Vorname')
 page.get_by_label('Y (mm)',exact=True).fill('36')
 page.get_by_label('Breite (mm)',exact=True).fill('110')
 page.get_by_label('Schriftgröße (pt)',exact=True).fill('11')
 page.get_by_role('button',name='Checkbox hinzufügen',exact=True).click()
 page.get_by_label('Feldname / Platzhalter',exact=True).fill('Zustimmung')
 page.get_by_label('Beschriftung in der Maske',exact=True).fill('Zustimmung')
 page.get_by_label('X (mm)',exact=True).fill('19.4');page.get_by_label('Y (mm)',exact=True).fill('62')
 page.wait_for_function('document.querySelector(".pdf-seite canvas")?.width>0')
 expect(page.get_by_text('PDF-Seite wird geladen …',exact=True)).not_to_be_visible()
 page.screenshot(path=str(out/'01-vorlageneditor.png'))
 page.keyboard.press('Escape')
 expect(page.get_by_role('heading',name='Eigene PDF-Felder und Vorlage',exact=True)).to_be_visible()
 assert page.get_by_label('Feldname / Platzhalter',exact=True).input_value()=='Zustimmung'
 page.get_by_role('button',name='Vorlage erstellen',exact=True).click()
 expect(page.get_by_text('Test: Vorlage konnte nicht gespeichert werden',exact=True)).to_be_visible()
 assert page.get_by_label('Feldname / Platzhalter',exact=True).input_value()=='Zustimmung'
 page.evaluate('window.failTemplate=false')
 page.get_by_role('button',name='Vorlage erstellen',exact=True).click()
 page.get_by_label('Vorname',exact=True).fill('Daniel Müller Łukasz €')
 page.get_by_label('Zustimmung',exact=True).check()
 page.wait_for_function('document.querySelector(".pdf-seite canvas")?.width>0')
 expect(page.get_by_text('PDF-Seite wird geladen …',exact=True)).not_to_be_visible()
 page.screenshot(path=str(out/'02-eingabemaske.png'))
 page.get_by_role('button',name='Ausfüllen und ablegen',exact=True).click()
 page.wait_for_function('window.calls.some(c=>c.cmd==="dokument_exportieren")')
 values=page.evaluate('window.calls.find(c=>c.cmd==="formular_ausfuellen").args')
 assert values['werte']=={'Vorname':'Daniel Müller Łukasz €','Zustimmung':True}
 assert values['basis']==1
 assert values['dokumentId']==workflow['vorlage']['document_id']
 exported=page.evaluate('window.calls.find(c=>c.cmd==="dokument_exportieren").args')
 assert exported['dokumentId']==workflow['ausgefuellt']['document_id']
 assert page.evaluate('window.pdfDocs.length')==3
 checks.append('PDF ohne Felder: Platzhalter und Checkbox definieren; echtes PDF.js rendert die Vorlage; Escape und Speicherfehler erhalten den Entwurf.')
 checks.append('Automatische Maske mit Vorname und Zustimmung; versionierter Ausfüllaufruf und Export des abgeleiteten Dokuments, Original bleibt vorhanden.')
 page.get_by_role('button',name='Projektordner exportieren …',exact=True).click()
 page.wait_for_function('window.calls.some(c=>c.cmd==="projektordner_exportieren")')
 assert page.evaluate('window.calls.find(c=>c.cmd==="projektordner_exportieren").args.projektId')==workflow['projekt']['id']
 page.screenshot(path=str(out/'03-dokumente.png'))
 page.locator('.aktennavigation').get_by_role('button',name='Büro / Benutzer / Lizenz',exact=True).click()
 page.get_by_role('button',name='Speicherort auswählen …',exact=True).click()
 assert not page.evaluate('window.calls.some(c=>c.cmd==="ablage_wechseln")')
 page.evaluate('window.allowed=true')
 page.get_by_role('button',name='Speicherort auswählen …',exact=True).click()
 expect(page.get_by_text('Test: Ziel konnte nicht geschrieben werden',exact=True)).to_be_visible()
 assert page.evaluate('window.currentRoot')=='/tmp/BauProjektIO'
 page.evaluate('window.failFolder=false')
 page.get_by_role('button',name='Speicherort auswählen …',exact=True).click()
 expect(page.get_by_text('3 Dateiversionen geprüft und übernommen. Die neue Ablage ist aktiv.',exact=True)).to_be_visible()
 assert page.evaluate('window.currentRoot')=='/tmp/NeueProjektablage'
 page.screenshot(path=str(out/'04-ablageeinstellungen.png'))
 checks.append('Ablageauswahl: Abbrechen ändert nichts; Fehler erhält den bisherigen Ort; Erfolg zeigt die neue Ablage. Projektordner-Export verwendet die ursprüngliche Projekt-ID.')
 for width in [1024,768]:
  page.set_viewport_size({'width':width,'height':900});assert not page.evaluate('document.documentElement.scrollWidth>innerWidth')
 assert not errors,errors
 browser.close()
(out/'ui-pruefung.json').write_text(json.dumps({'checks':checks,'javascript_errors':errors,'pdf_rendering':'real PDF.js worker; input PDFs generated through actual Rust/DMS integration test','transport':'controlled Tauri IPC for UI actions'},ensure_ascii=False,indent=2)+'\n')
print(json.dumps(checks,ensure_ascii=False,indent=2))
